INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "李文忠", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋姊子，1354年归舅获赐朱姓。", "biography": null, "status": "draft", "id": "937816d2-8a96-5b84-9cae-f26cdcacfa7b"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"name": "刘基", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青田人，反对招抚方国珍被谪，曾任儒学副提举。", "biography": null, "status": "draft", "id": "bb5b8872-dbd3-576b-b02d-3b844e5a38e7"}, {"name": "朱亮祖", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "义兵元帅，先降朱又叛，1357年宁国被擒获释。", "biography": null, "status": "draft", "id": "5c1a83a7-a770-5dc7-9fbd-e713e03e8e72"}, {"name": "库库特穆尔（察罕特穆尔养子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "本姓王名保保，察罕外甥，养为子；继掌其军。", "biography": null, "status": "draft", "id": "c00ceaa1-c47d-5d7f-bbe7-4c2ba9cfe8df"}, {"name": "纳克楚（元太平万户）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "穆呼哩裔孙，1355年被朱俘后放北归。", "biography": null, "status": "draft", "id": "89f87003-83bd-5c55-b910-1c5e3f351489"}, {"name": "沐英", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，父母亡，朱元璋收养、赐朱姓。", "biography": null, "status": "draft", "id": "c9e9d78a-2557-5892-876e-b1e99dd22bed"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "胡惟庸", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴臣，与张昶相善，1367年张案为回述交往，不补其参与检举。", "biography": null, "status": "draft", "id": "a3692261-9b8a-509a-b529-4205572cb210"}, {"name": "汪广洋", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年任朱元璋帅府令史。", "biography": null, "status": "draft", "id": "ac800e6b-ef48-5dc3-964b-d67d64245b02"}]'::jsonb)
