INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷召回邓愈和汤和", "description": "洪武七年十二月戊戌，明廷召邓愈和汤和返回。", "start_year": 1375, "end_year": 1375, "time_original": "洪武七年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07b0e349-7b09-5bc6-8bee-cd399b97b84f"}, {"title": "本纪记这一年多地入贡", "description": "洪武七年，史书列举阿难功德国、暹罗、琉球、三佛齐、乌斯藏、撒里和畏兀儿等地入贡，没有分别记到达日期。 按原历纪年，事情发生在公元1374至1375年之间。", "start_year": null, "end_year": null, "time_original": "洪武七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8664369f-0d9a-5bf6-bba8-3ef9c8b81f26"}, {"title": "明廷增列鸡笼山功臣庙祭祀对象", "description": "洪武八年正月辛未，明廷在鸡笼山功臣庙增加祭祀对象一百零八人。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb03840d-3333-5434-b467-857c219d06fd"}, {"title": "明廷命官员给无依贫民房屋衣食", "description": "正月癸酉，明廷命地方主管官员查访无处求助的贫民，提供住屋、衣服和食物。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "65b54208-b140-59f3-9c03-9fc54ce01b73"}, {"title": "邓愈、汤和等奉命屯戍北平等地", "description": "正月辛巳，明廷命邓愈、汤和等十三人屯戍北平、陕西和河南。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7bafdb96-afcd-5645-87bc-29870fd32a12"}, {"title": "明廷下诏在各地立社学", "description": "正月丁亥，明廷下诏在各地设立社学。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b1cdc8d-c65f-58c3-8c90-0bba1803e09b"}, {"title": "黄河在开封决口，明廷调民夫堵塞", "description": "同月，黄河在开封决口，明廷调集民夫堵塞决口。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0c18c4e-9178-564d-9200-35fcaa7a230d"}, {"title": "明廷把部分获宽宥者送到凤阳服役", "description": "二月甲午，明廷宽宥杂犯死罪以下以及因私罪获罪的官员，把他们发往凤阳服役、屯种赎罪。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ee658fc8-47a0-5c39-a8c5-f8a371cd15db"}, {"title": "明廷召回徐达等人，傅友德继续镇守北平", "description": "二月，明廷召徐达、李文忠和冯胜返回，留傅友德等镇守北平。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fc811154-5858-5e54-b14e-b2bd1cb9d238"}, {"title": "明廷制定纸钞制度", "description": "三月辛酉，明廷制定纸钞制度。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d4bc602-daf1-5c54-83d8-66cab155bffb"}, {"title": "明廷停止宝源局铸钱", "description": "三月辛巳，明廷停止宝源局铸钱。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d30ceb12-11b0-5a05-ab27-b891da409a1a"}, {"title": "明廷停止营建中都", "description": "四月，明廷停止营建中都。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "27f4ce02-9259-5928-97f4-629dbc0525c1"}, {"title": "明廷免除彰德等地受灾田租", "description": "四月，明廷免去彰德、大名、临洮、平凉和河州受灾地区的田租。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "016ddc4e-2042-5091-aced-d49be41991b5"}, {"title": "已致仕的诚意伯刘基去世", "description": "四月，已经退休的诚意伯刘基去世。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "35481faa-6118-5998-9a31-90f4f8054341"}, {"title": "朱亮祖和傅友德镇守北平", "description": "五月己巳，永嘉侯朱亮祖与傅友德镇守北平。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "264f3b6d-a1f4-504c-bb28-44d67794861c"}, {"title": "明廷派指挥同知率兵进贵州", "description": "六月壬寅，本纪记有指挥同知率军平定贵州一带。人名与动词边界须回查。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58bad8cb-1997-5d11-baf9-c5c6fbe23b9e"}, {"title": "洪武八年七月初一日食", "description": "七月初一，本纪记发生日食。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ad318c29-e901-5688-96ea-3480f5946e53"}, {"title": "明廷改建太庙", "description": "七月辛酉，明廷改建太庙。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "091670ae-5787-5527-9e25-229d79ba413c"}, {"title": "明廷准许官员不等批复即可奔父母丧", "description": "七月戊辰，明廷下诏，官员遇父母去世可立即奔丧，无须等待批复。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "611565ee-fde6-56d1-acb3-e28788e244cf"}, {"title": "明廷免除应天等地受灾田租", "description": "七月丁丑，明廷免除应天、太平、宁国、镇江及蕲、黄等地受灾地区的田租。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1aa0268e-76fe-5b99-8216-e2d0db560dde"}, {"title": "扩廓帖木儿去世", "description": "八月己酉，元朝将领扩廓帖木儿去世。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f69bfff3-aec3-5c37-8994-8a9abe6e9941"}, {"title": "明廷下诏荐举有才行的富民", "description": "十月丁亥，明廷下诏，荐举平时品行端正、通晓时务的富民。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "08fde2bc-92c1-5459-a1cd-8ae5cd9890f3"}, {"title": "明廷命皇太子及诸王在中都演习武事", "description": "十月壬子，明廷命皇太子和诸王在中都学习、演习武事。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "37d8ada7-5090-5ad1-9a32-faa5d23565f8"}, {"title": "明廷在圜丘举行祭祀", "description": "十一月丁丑，明廷在圜丘举行祭祀。", "start_year": 1375, "end_year": 1375, "time_original": "洪武八年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15a76404-43fa-5702-a2c6-481a3ec9ef8e"}, {"title": "洪武八年十二月京师地震", "description": "十二月戊子，京师发生地震。 按原历纪年，事情发生在公元1375至1376年之间。", "start_year": null, "end_year": null, "time_original": "洪武八年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44851edf-cf9f-534f-b4f6-9721c7599c29"}, {"title": "明廷派使者救济苏州等地水灾", "description": "十二月甲寅，明廷派使者救济苏州、湖州、嘉兴、松江、常州、太平、宁国、杭州受水灾的百姓。 按原历纪年，事情发生在公元1375至1376年之间。", "start_year": null, "end_year": null, "time_original": "洪武八年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7410075f-9db9-5961-8f8d-1360042c945a"}, {"title": "马云、叶旺击败进攻辽东的纳哈出", "description": "同月，纳哈出进攻辽东，明军指挥马云和叶旺将其击败。 按原历纪年，事情发生在公元1375至1376年之间。", "start_year": null, "end_year": null, "time_original": "洪武八年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1239867-1db1-522e-baf6-39b72fed4f14"}, {"title": "本纪列举洪武八年入贡记载", "description": "洪武八年，本纪记撒里、高丽、占城、暹罗、日本、爪哇和三佛齐入贡，未分列各次月份。 按原历纪年，事情发生在公元1375至1376年之间。", "start_year": null, "end_year": null, "time_original": "洪武八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fa2adb9e-15cf-533b-8980-55811de48b73"}, {"title": "汤和等奉命在延安备边", "description": "洪武九年正月，明廷命汤和、傅友德、蓝玉、王弼和丁玉到延安加强边防。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f8d42897-5184-5920-abf5-a07c91727bc5"}, {"title": "明廷免除多地当年租赋", "description": "三月己卯，朱元璋下诏说，各地久受兵役、宫室营建和转运粮饷之苦，因此免除淮、扬、安、徽、池五府以及山西、陕西等地当年的租赋。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d6234e9d-ecbf-5738-9a54-2ef1028f849e"}, {"title": "京师久旱后降雨", "description": "四月庚戌，京师自上年八月以来久未下雨，这一天开始下雨。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "24ff2069-0293-5df1-b3ef-4a9d6f6e93a8"}, {"title": "京师连续下雨后放晴", "description": "五月癸酉，本纪记京师自四月庚戌起接连下雨，到这一天才放晴。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2797a1c9-e5ba-5448-9ab1-742d465e804e"}, {"title": "明廷将行中书省改为承宣布政使司", "description": "六月甲午，明廷把行中书省改为承宣布政使司。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "93340e3b-88e9-5ca0-a083-98cf19ace76a"}, {"title": "李文忠返回", "description": "六月辛丑，李文忠返回。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c4579b5-8f61-5378-bb73-383fdd6d4e36"}, {"title": "洪武九年七月初一日食", "description": "七月初一，本纪记发生日食。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f20937cf-ee0b-57c9-a166-6f88f2b4bf91"}, {"title": "明廷免江南部分水灾田租并救济永平", "description": "七月，明廷免苏州、松江、嘉兴、湖州受水灾地区的田租，并救济永平旱灾。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "53b7e4c7-75a3-5530-ab14-9372b36ecfec"}, {"title": "傅友德击败进攻延安的元军", "description": "七月，元将伯颜帖木儿进攻延安，傅友德击败来军，接受其归降。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94107b8a-d3d8-5d84-803c-fda62d76ccde"}, {"title": "明廷派官员巡视历代帝王陵寝", "description": "八月己酉，明廷派官员巡视历代帝王陵寝，禁止附近割草和放牧，并设守陵户。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23b56387-da5c-5734-afe8-f5077766bc7f"}, {"title": "明廷因灾异下诏征求直言", "description": "闰九月庚寅，明廷因史书所称的灾异下诏，希望臣下直言。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年闰九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "85c43f9d-d5a0-547e-9284-c84c96fd4e02"}, {"title": "太庙建成，明廷举行合享礼", "description": "十月己未，太庙建成，此后明廷在太庙举行合享礼。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d9cee2f1-16b1-5f08-a661-c45e9bf46130"}, {"title": "明廷命秦王等到凤阳练兵", "description": "十月丙子，明廷命秦、晋、燕、吴、楚、齐诸王到凤阳整练军队。", "start_year": 1376, "end_year": 1376, "time_original": "洪武九年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "467d9404-8db3-5419-8fc7-ae626bbf22f9"}, {"title": "明廷在圜丘举行祭祀", "description": "十一月壬午，明廷在圜丘举行祭祀。 按原历纪年，事情发生在公元1376至1377年之间。", "start_year": null, "end_year": null, "time_original": "洪武九年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f10b7e03-1365-58d5-b0ad-22ea356996fb"}, {"title": "明廷迁无产百姓到凤阳耕种", "description": "十一月戊子，明廷将山西和真定没有产业的百姓迁到凤阳耕种。 按原历纪年，事情发生在公元1376至1377年之间。", "start_year": null, "end_year": null, "time_original": "洪武九年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "640e42b5-9384-52a9-a141-1f27689702ff"}, {"title": "明廷救济畿内等地水灾", "description": "十二月甲寅，明廷救济京畿、浙江和湖北受水灾的百姓。", "start_year": 1377, "end_year": 1377, "time_original": "洪武九年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5227ef4-f457-5555-8e75-b8f40e91e301"}, {"title": "沐英奉命赴陕西访察民情", "description": "十二月己卯，明廷派都督同知沐英乘驿车到陕西，了解百姓的困难。", "start_year": 1377, "end_year": 1377, "time_original": "洪武九年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "66572fbf-e6ab-55c3-ada9-3db4cfbc4033"}, {"title": "本纪列举洪武九年入贡记载", "description": "洪武九年，本纪记览邦、琉球、安南、日本、乌斯藏和高丽进贡，未分别载明日期。 按原历纪年，事情发生在公元1376至1377年之间。", "start_year": null, "end_year": null, "time_original": "洪武九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b3ed3160-96c8-57d1-8387-8dbb9d6e4cd5"}, {"title": "明廷增补秦、晋、燕三王府护卫", "description": "洪武十年正月辛卯，明廷从羽林等卫调军，增补秦、晋、燕三个王府的护卫。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "409230d7-5dcb-5f81-9dad-551b8490f1eb"}, {"title": "邓愈、沐英率兵进攻吐番", "description": "四月己酉，明廷命邓愈为征西将军，沐英为副将。两人率兵进攻本纪所称的吐番，击败来军。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0294b6d2-8fd5-57c6-ae28-766b7a9c32be"}, {"title": "李善长和李文忠总领三机构议军国事务", "description": "五月庚子，韩国公李善长、曹国公李文忠总领中书省、大都督府、御史台，商议军国大事。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "def4d6fc-1bd6-5bfb-880a-1dcea92def05"}, {"title": "赵乾因赈济迟缓被处死", "description": "五月丙午，户部主事赵乾因赈济荆、蕲两地迟缓而被处死。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72018e24-e8a9-5399-a349-ef3c9d29a4bc"}, {"title": "明廷准许臣民密封文书直达御前", "description": "六月丁巳，明廷下诏，臣民如有事上报，可以将文书密封后直接送达皇帝。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b5391755-778d-5150-a07f-3d7a6029a63c"}, {"title": "明廷命皇太子裁决政事并上奏", "description": "六月丙寅，明廷规定政事先交皇太子裁决，再向皇帝报告。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b28a6f29-5c8a-5bc0-bed7-210c89581fba"}, {"title": "明廷设立通政司", "description": "七月甲申，明廷设立通政司。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b95ce8c-a420-5172-b12b-ea4e945d71af"}, {"title": "明廷开始派御史巡按州县", "description": "同月，明廷开始派御史到州县巡察。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b85b60e-4afe-5650-95e9-e0ba4f7b8318"}, {"title": "明廷在南郊改建大祀殿", "description": "八月庚戌，明廷在南郊改建大祀殿。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8790c2d9-bddc-57fc-a445-0b0bae36a2d2"}, {"title": "明廷选武臣子弟入国子监读书", "description": "八月癸丑，明廷选拔武臣子弟进入国子监读书。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41c1b401-ed72-5741-8f86-6d4dacfa0e34"}, {"title": "明廷救济绍兴、金华和衢州水灾", "description": "九月丙申，明廷救济绍兴、金华、衢州受水灾的百姓。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3c53edc1-a20b-56c1-b197-fb84d4cf097b"}, {"title": "胡惟庸升任左丞相", "description": "洪武10年（1377年）九月，胡惟庸升任左丞相。", "start_year": 1377, "end_year": 1377, "time_original": "洪武10年（1377年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6e95cad9-2202-5abb-ae1c-098ef3963c83"}, {"title": "汪广洋恢复右丞相职务", "description": "洪武10年（1377年）九月，汪广洋恢复右丞相职务。", "start_year": 1377, "end_year": 1377, "time_original": "洪武10年（1377年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ea89ad1c-2413-59a3-8506-b5161ef14c8a"}, {"title": "明廷封沐英为西平侯", "description": "十月戊午，明廷封沐英为西平侯。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "111722d7-a8fe-5937-83d1-c1a7efbff3f9"}, {"title": "明廷赐百官公田", "description": "十月辛酉，明廷赐给百官公田。", "start_year": 1377, "end_year": 1377, "time_original": "洪武十年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "570aba05-566e-5623-bf12-e3ea8b14efb7"}, {"title": "卫国公邓愈去世", "description": "十一月癸未，卫国公邓愈去世。 按原历纪年，事情发生在公元1377至1378年之间。", "start_year": null, "end_year": null, "time_original": "洪武十年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ccdfbfb5-841b-5904-8e1c-0f04b488819f"}, {"title": "明廷在奉天殿合祭天地", "description": "十一月丁亥，明廷在奉天殿合祭天地。 按原历纪年，事情发生在公元1377至1378年之间。", "start_year": null, "end_year": null, "time_original": "洪武十年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6aa1f81e-c147-53d2-b221-aeb321611657"}, {"title": "明廷免河南等地田租", "description": "同月，明廷免除河南、陕西、广东和湖广的田租。 按原历纪年，事情发生在公元1377至1378年之间。", "start_year": null, "end_year": null, "time_original": "洪武十年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "25ab5592-05b9-50fd-ad57-01ca2a230c8a"}, {"title": "洪武十年十二月初一日食", "description": "十二月初一，本纪记发生日食。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a9e8df0e-ca6a-501b-b19e-fa62ce528efd"}, {"title": "明廷登记故功臣后代并分别授官", "description": "十二月丁未，明廷登记五百多名已故功臣的子孙，按不同等级授予官职。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "795b2ee1-d294-540b-92f5-b2d2d4dd7534"}]'::jsonb)
